package com.opensocket.aievent.database.persistence.issuerelay;
import java.time.OffsetDateTime; import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import com.opensocket.aievent.core.issuetracking.relay.*; import com.opensocket.aievent.database.persistence.issuerelay.dao.RelayGovernanceDao; import com.opensocket.aievent.database.persistence.spi.DatabaseRepositoryAdapter;
@DatabaseRepositoryAdapter @ConditionalOnProperty(prefix="issue-relay",name="store",havingValue="MYBATIS",matchIfMissing=true)
public class MybatisRelayGovernanceRepository implements RelayGovernanceRepository {
 private final RelayGovernanceDao dao; public MybatisRelayGovernanceRepository(RelayGovernanceDao dao){this.dao=dao;}
 public CanonicalIssueRelation saveRelation(CanonicalIssueRelation v){dao.upsertRelation(in(v));return v;} public boolean saveRelationExpectedVersion(CanonicalIssueRelation v,long e){return dao.updateRelationExpectedVersion(in(v),e)==1;} public Optional<CanonicalIssueRelation> findRelation(String t,String id){return Optional.ofNullable(dao.findRelation(t,id)).map(this::out);} public List<CanonicalIssueRelation> listRelations(String t,CanonicalRelationStatus s,int n){return dao.listRelations(t,s==null?null:s.name(),lim(n)).stream().map(this::out).toList();}
 public RelayTopology saveTopology(RelayTopology v){dao.upsertTopology(in(v));return v;} public boolean saveTopologyExpectedVersion(RelayTopology v,long e){return dao.updateTopologyExpectedVersion(in(v),e)==1;} public Optional<RelayTopology> findTopology(String t,String id){return Optional.ofNullable(dao.findTopology(t,id)).map(this::out);} public List<RelayTopology> listTopologies(String t,RelayTopologyStatus s,int n){return dao.listTopologies(t,s==null?null:s.name(),lim(n)).stream().map(this::out).toList();}
 public RelayEdge saveEdge(RelayEdge v){dao.upsertEdge(in(v));return v;} public boolean saveEdgeExpectedVersion(RelayEdge v,long e){return dao.updateEdgeExpectedVersion(in(v),e)==1;} public Optional<RelayEdge> findEdge(String t,String id){return Optional.ofNullable(dao.findEdge(t,id)).map(this::out);} public List<RelayEdge> listEdges(String t,String top,RelayEdgeStatus s,int n){return dao.listEdges(t,blank(top),s==null?null:s.name(),lim(n)).stream().map(this::out).toList();} public List<RelayEdge> claimDueEdges(String t,OffsetDateTime due,int n){return dao.claimDueEdges(t,due,lim(n)).stream().map(this::out).toList();}
 public RelayCompensation saveCompensation(RelayCompensation v){dao.upsertCompensation(in(v));return v;} public boolean saveCompensationExpectedVersion(RelayCompensation v,long e){return dao.updateCompensationExpectedVersion(in(v),e)==1;} public Optional<RelayCompensation> findCompensation(String t,String id){return Optional.ofNullable(dao.findCompensation(t,id)).map(this::out);} public List<RelayCompensation> listCompensations(String t,String top,RelayCompensationStatus s,int n){return dao.listCompensations(t,blank(top),s==null?null:s.name(),lim(n)).stream().map(this::out).toList();}
 public RelayEvent appendEvent(RelayEvent v){dao.insertEvent(in(v));return v;} public Optional<RelayEvent> latestEvent(String t,String type,String id){return Optional.ofNullable(dao.latestEvent(t,type,id)).map(this::out);} public List<RelayEvent> listEvents(String t,String type,String id,int n){return dao.listEvents(t,type,id,lim(n)).stream().map(this::out).toList();} public String mode(){return "MYBATIS_POSTGRESQL";} private int lim(int n){return Math.max(1,Math.min(n,1000));} private String blank(String s){return s==null||s.isBlank()?null:s.trim();}
 private CanonicalIssueRelationPo in(CanonicalIssueRelation v){var p=new CanonicalIssueRelationPo();p.setTenantId(v.tenantId());p.setRelationId(v.relationId());p.setRelationType(v.relationType());p.setParentTaskId(v.parentTaskId());p.setChildTaskId(v.childTaskId());p.setSourceTaskIssueLinkId(v.sourceTaskIssueLinkId());p.setTargetTaskIssueLinkId(v.targetTaskIssueLinkId());p.setStatus(v.status().name());p.setVersion(v.version());p.setCreatedAt(v.createdAt());p.setUpdatedAt(v.updatedAt());p.setCorrelationId(v.correlationId());return p;} private CanonicalIssueRelation out(CanonicalIssueRelationPo p){return new CanonicalIssueRelation(p.getTenantId(),p.getRelationId(),p.getRelationType(),p.getParentTaskId(),p.getChildTaskId(),p.getSourceTaskIssueLinkId(),p.getTargetTaskIssueLinkId(),CanonicalRelationStatus.valueOf(p.getStatus()),p.getVersion(),p.getCreatedAt(),p.getUpdatedAt(),p.getCorrelationId());}
 private RelayTopologyPo in(RelayTopology v){var p=new RelayTopologyPo();p.setTenantId(v.tenantId());p.setTopologyId(v.topologyId());p.setCanonicalRelationId(v.canonicalRelationId());p.setTopologyType(v.topologyType().name());p.setStatus(v.status().name());p.setEdgeCount(v.edgeCount());p.setSyncedEdgeCount(v.syncedEdgeCount());p.setFailedEdgeCount(v.failedEdgeCount());p.setDecisionEdgeCount(v.decisionEdgeCount());p.setVersion(v.version());p.setCreatedAt(v.createdAt());p.setUpdatedAt(v.updatedAt());p.setCorrelationId(v.correlationId());return p;} private RelayTopology out(RelayTopologyPo p){return new RelayTopology(p.getTenantId(),p.getTopologyId(),p.getCanonicalRelationId(),RelayTopologyType.valueOf(p.getTopologyType()),RelayTopologyStatus.valueOf(p.getStatus()),p.getEdgeCount(),p.getSyncedEdgeCount(),p.getFailedEdgeCount(),p.getDecisionEdgeCount(),p.getVersion(),p.getCreatedAt(),p.getUpdatedAt(),p.getCorrelationId());}
 private RelayEdgePo in(RelayEdge v){var p=new RelayEdgePo();p.setTenantId(v.tenantId());p.setEdgeId(v.edgeId());p.setTopologyId(v.topologyId());p.setConnectionId(v.connectionId());p.setProjectMappingId(v.projectMappingId());p.setProviderType(v.providerType());p.setExternalProjectId(v.externalProjectId());p.setSourceExternalIssueId(v.sourceExternalIssueId());p.setTargetExternalIssueId(v.targetExternalIssueId());p.setEdgeType(v.edgeType().name());p.setRelationType(v.relationType());p.setSourceMarker(v.sourceMarker());p.setStatus(v.status().name());p.setAttemptCount(v.attemptCount());p.setNextAttemptAt(v.nextAttemptAt());p.setProviderObjectId(v.providerObjectId());p.setLastErrorCode(v.lastErrorCode());p.setLastErrorMessage(v.lastErrorMessage());p.setVersion(v.version());p.setCreatedAt(v.createdAt());p.setUpdatedAt(v.updatedAt());p.setCorrelationId(v.correlationId());return p;} private RelayEdge out(RelayEdgePo p){return new RelayEdge(p.getTenantId(),p.getEdgeId(),p.getTopologyId(),p.getConnectionId(),p.getProjectMappingId(),p.getProviderType(),p.getExternalProjectId(),p.getSourceExternalIssueId(),p.getTargetExternalIssueId(),RelayEdgeType.valueOf(p.getEdgeType()),p.getRelationType(),p.getSourceMarker(),RelayEdgeStatus.valueOf(p.getStatus()),p.getAttemptCount(),p.getNextAttemptAt(),p.getProviderObjectId(),p.getLastErrorCode(),p.getLastErrorMessage(),p.getVersion(),p.getCreatedAt(),p.getUpdatedAt(),p.getCorrelationId());}
 private RelayCompensationPo in(RelayCompensation v){var p=new RelayCompensationPo();p.setTenantId(v.tenantId());p.setCompensationId(v.compensationId());p.setTopologyId(v.topologyId());p.setCanonicalRelationId(v.canonicalRelationId());p.setReasonCode(v.reasonCode());p.setRequestedBy(v.requestedBy());p.setStatus(v.status().name());p.setTotalEdges(v.totalEdges());p.setCompensatedEdges(v.compensatedEdges());p.setFailedEdges(v.failedEdges());p.setVersion(v.version());p.setCreatedAt(v.createdAt());p.setUpdatedAt(v.updatedAt());p.setCorrelationId(v.correlationId());return p;} private RelayCompensation out(RelayCompensationPo p){return new RelayCompensation(p.getTenantId(),p.getCompensationId(),p.getTopologyId(),p.getCanonicalRelationId(),p.getReasonCode(),p.getRequestedBy(),RelayCompensationStatus.valueOf(p.getStatus()),p.getTotalEdges(),p.getCompensatedEdges(),p.getFailedEdges(),p.getVersion(),p.getCreatedAt(),p.getUpdatedAt(),p.getCorrelationId());}
 private RelayEventPo in(RelayEvent v){var p=new RelayEventPo();p.setTenantId(v.tenantId());p.setEventId(v.eventId());p.setAggregateType(v.aggregateType());p.setAggregateId(v.aggregateId());p.setEventType(v.eventType().name());p.setActorId(v.actorId());p.setReasonCode(v.reasonCode());p.setMetadataJson(v.metadataJson());p.setPreviousEventHash(v.previousEventHash());p.setEventHash(v.eventHash());p.setOccurredAt(v.occurredAt());p.setCorrelationId(v.correlationId());return p;} private RelayEvent out(RelayEventPo p){return new RelayEvent(p.getTenantId(),p.getEventId(),p.getAggregateType(),p.getAggregateId(),RelayEventType.valueOf(p.getEventType()),p.getActorId(),p.getReasonCode(),p.getMetadataJson(),p.getPreviousEventHash(),p.getEventHash(),p.getOccurredAt(),p.getCorrelationId());}
}
